    case valid(list: VerifiedList
    )
    case invalid(failure: ListFailure
    )





}

#if compiler(>=6)
extension SignedListResult: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSignedListResult: FfiConverterRustBuffer {
    typealias SwiftType = SignedListResult

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SignedListResult {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .valid(list: try FfiConverterTypeVerifiedList.read(from: &buf)
        )
        
        case 2: return .invalid(failure: try FfiConverterTypeListFailure.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SignedListResult, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .valid(list):
            writeInt(&buf, Int32(1))
            FfiConverterTypeVerifiedList.write(list, into: &buf)
            
        
        case let .invalid(failure):
            writeInt(&buf, Int32(2))
            FfiConverterTypeListFailure.write(failure, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSignedListResult_lift(_ buf: RustBuffer) throws -> SignedListResult {
    return try FfiConverterTypeSignedListResult.lift(buf)
}

